CREATE TABLE users (
 id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
 email VARCHAR(255) NOT NULL UNIQUE, password VARCHAR(255), display_name VARCHAR(80), job_title VARCHAR(80), bio VARCHAR(500), avatar_image TEXT, recovery_code_hash VARCHAR(255)
);
CREATE TABLE projects (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name VARCHAR(255) NOT NULL UNIQUE, description VARCHAR(255), owner_email VARCHAR(255) NOT NULL, version BIGINT);
CREATE TABLE project_member (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, project_id BIGINT, email VARCHAR(255) NOT NULL, role VARCHAR(255) NOT NULL, UNIQUE(project_id,email));
CREATE TABLE user_stories (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, title VARCHAR(255) NOT NULL, description VARCHAR(255), acceptance_criteria VARCHAR(255) NOT NULL, story_points INTEGER NOT NULL, priority_id INTEGER NOT NULL, project_id BIGINT NOT NULL, created_at TIMESTAMP WITH TIME ZONE, version BIGINT);
CREATE TABLE sprint (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name VARCHAR(255), goal VARCHAR(255), status VARCHAR(255), total_story_points INTEGER NOT NULL, project_id BIGINT, created_at TIMESTAMP WITH TIME ZONE, completed_at TIMESTAMP WITH TIME ZONE, version BIGINT);
CREATE TABLE task (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, title VARCHAR(255), description VARCHAR(255), status VARCHAR(255), is_blocked BOOLEAN NOT NULL, block_reason VARCHAR(255), project_id BIGINT, sprint_id BIGINT, story_id BIGINT, story_points INTEGER NOT NULL, created_at TIMESTAMP WITH TIME ZONE, started_at TIMESTAMP WITH TIME ZONE, completed_at TIMESTAMP WITH TIME ZONE, due_at TIMESTAMP WITH TIME ZONE, version BIGINT);
CREATE TABLE task_status_history (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, task_id BIGINT, project_id BIGINT, sprint_id BIGINT, status VARCHAR(255), changed_at TIMESTAMP WITH TIME ZONE, actor_email VARCHAR(255));
CREATE TABLE task_comment (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, task_id BIGINT, project_id BIGINT, author_email VARCHAR(255), message VARCHAR(255), created_at TIMESTAMP WITH TIME ZONE);
CREATE TABLE task_attachment (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, task_id BIGINT, project_id BIGINT, name VARCHAR(255), url VARCHAR(2000), storage_key VARCHAR(255), created_at TIMESTAMP WITH TIME ZONE);
CREATE TABLE activity_event (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, project_id BIGINT, event_type VARCHAR(255), summary VARCHAR(255), actor_email VARCHAR(255), created_at TIMESTAMP WITH TIME ZONE);
CREATE TABLE notification (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, project_id BIGINT, recipient_email VARCHAR(255), message VARCHAR(255), is_read BOOLEAN NOT NULL, created_at TIMESTAMP WITH TIME ZONE);
CREATE TABLE password_reset_tokens (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, user_id BIGINT NOT NULL REFERENCES users(id), token_hash VARCHAR(64) NOT NULL UNIQUE, expires_at TIMESTAMP WITH TIME ZONE NOT NULL);
CREATE INDEX task_project_idx ON task(project_id);
CREATE INDEX task_sprint_idx ON task(sprint_id);
CREATE INDEX sprint_project_idx ON sprint(project_id);
CREATE INDEX story_project_idx ON user_stories(project_id);
CREATE INDEX activity_project_time_idx ON activity_event(project_id,created_at DESC);
CREATE INDEX history_task_time_idx ON task_status_history(task_id,changed_at DESC);
CREATE INDEX notification_recipient_time_idx ON notification(recipient_email,created_at DESC);
